SELECT t.*
FROM agent_trace t
JOIN conversation c ON c.id = t.conversation_id

    c.user_id = #{userId}

        AND t.conversation_id = #{conversationId}


ORDER BY t.id DESC
LIMIT #{limit}

SELECT t.*
FROM agent_trace t
JOIN conversation c ON c.id = t.conversation_id
WHERE t.trace_id = #{traceId}
  AND c.user_id = #{userId}
LIMIT 1
